function groupItems() {
  const groups = new Map<string, NavItem[]>();
  for (const item of SETTINGS_NAV) {
    const list = groups.get(item.group) ?? [];
    list.push(item);
    groups.set(item.group, list);
  }
  return [...groups.entries()];
}

