function PageHeader({ title, description, badge }: { title: string; description: string; badge?: string }) {
  return <div className="border-b border-border pb-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><h2 className="text-2xl font-bold tracking-tight">{title}</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-muted-foreground">{description}</p></div>{badge && <span className="inline-flex w-fit items-center gap-2 rounded-full border border-accent/20 bg-accent-soft px-3 py-1.5 text-xs font-semibold text-accent-ink">{badge}</span>}</div></div>;
}

function CardSection({ title, description, children, className = "" }: { title: string; description?: string; children: React.ReactNode; className?: string }) {
  return <section className={`rounded-2xl border border-border bg-background p-5 sm:p-6 ${className}`}><div className="mb-5"><h3 className="font-semibold">{title}</h3>{description && <p className="mt-1 text-sm leading-5 text-muted-foreground">{description}</p>}</div>{children}</section>;
}

function SaveBar({ dirty, saving, onDiscard, onSave }: { dirty: boolean; saving: boolean; onDiscard: () => void; onSave: () => void }) {
  if (!dirty) return null;
  return <div className="sticky bottom-4 z-20 flex flex-col gap-3 rounded-2xl border border-border bg-background/95 p-3 shadow-xl backdrop-blur sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-2 text-sm font-medium"><span className="size-2 rounded-full bg-accent" />Unsaved changes</div><div className="flex gap-2"><Button variant="ghost" onClick={onDiscard} disabled={saving}>Discard</Button><Button onClick={onSave} disabled={saving}><Save className="mr-2 size-4" />{saving ? "Saving…" : "Save changes"}</Button></div></div>;
}

function ToggleRow({ label, description, checked, onChange }: { label: string; description: string; checked: boolean; onChange: (value: boolean) => void }) {
  return <div className="flex items-center justify-between gap-5 rounded-xl border border-border p-4"><div><p className="text-sm font-semibold">{label}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{description}</p></div><Switch checked={checked} onCheckedChange={onChange} /></div>;
}

function Field({ label, value, onChange, type = "text", placeholder, disabled = false }: { label: string; value: string; onChange: (value: string) => void; type?: string; placeholder?: string; disabled?: boolean }) {
  return <label className="block text-sm font-medium">{label}<Input className="mt-2" type={type} value={value} placeholder={placeholder} disabled={disabled} onChange={(event) => onChange(event.target.value)} /></label>;
}

function SelectField({ label, value, onChange, options }: { label: string; value: string; onChange: (value: string) => void; options: string[] }) {
  return <label className="block text-sm font-medium">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className="mt-2 h-10 w-full rounded-md border border-border bg-background px-3 text-sm outline-none focus:border-accent">{options.map((option) => <option key={option} value={option}>{option}</option>)}</select></label>;
}

function useStoreData() {
  const { store, userId } = useStoreContext();
  const [data, setData] = useState<any>({ store: null, profile: null, config: null, advanced: {}, online: null });
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    if (!store?.id) return;
    setLoading(true);
    const [{ data: storeRow }, { data: profile }, { data: config }, { data: advanced }, { data: online }] = await Promise.all([
      db.from("stores").select("*").eq("id", store.id).maybeSingle(),
      db.from("profiles").select("full_name,email,created_at,updated_at").eq("id", userId).maybeSingle(),
      db.from("storefront_configs").select("*").eq("store_id", store.id).maybeSingle(),
      db.from("store_advanced_settings").select("settings,updated_at").eq("store_id", store.id).maybeSingle(),
      db.from("online_stores").select("*").eq("store_id", store.id).maybeSingle(),
    ]);
    setData({ store: storeRow ?? store, profile, config, advanced: advanced?.settings ?? {}, online });
    setLoading(false);
  }, [store?.id, userId]);

  useEffect(() => { void load(); }, [load]);
  return { ...data, loading, reload: load };
}

async function saveAdvanced(storeId: string, current: Record<string, unknown>, patch: Record<string, unknown>) {
  const settings = { ...current, ...patch };
  const { error } = await db.from("store_advanced_settings").upsert({ store_id: storeId, settings, updated_at: new Date().toISOString() }, { onConflict: "store_id" });
  if (error) throw new Error(error.message);
  return settings;
}

