function ColorInput({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <label className="block text-sm font-medium">{label}<div className="mt-2 flex gap-2"><input type="color" value={value} onChange={(e) => onChange(e.target.value)} className="h-10 w-12 rounded-md border border-border bg-background p-1"/><Input value={value} onChange={(e) => onChange(e.target.value)} /></div></label>; }

function StaffSettingsPage() {
  const { store, role } = useStoreContext(); const canManage = role === "owner" || role === "manager"; const [staff, setStaff] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [selected, setSelected] = useState<any | null>(null); const [creating, setCreating] = useState(false); const [form, setForm] = useState({ name: "", role: "cashier", pin: "" }); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => { if (!store?.id) return; setLoading(true); const { data, error } = await db.rpc("list_staff_accounts", { _store_id: store.id }); if (error) toast.error(error.message); setStaff((data ?? []) as any[]); setLoading(false); }, [store?.id]); useEffect(() => { void load(); }, [load]);
  const create = async () => { if (!store?.id || !canManage || !form.name.trim() || !/^\d{4,6}$/.test(form.pin)) return toast.error("Enter a name and a 4–6 digit PIN."); setBusy(true); try { const { data, error } = await db.rpc("create_staff_account", { _store_id: store.id, _name: form.name.trim(), _pin: form.pin, _role: form.role }); if (error) throw new Error(error.message); const created = Array.isArray(data) ? data[0] : data; if (!created?.id) throw new Error("Staff creation was not confirmed."); setCreating(false); setForm({ name: "", role: "cashier", pin: "" }); toast.success(`${created.name} was added.`); await load(); } catch (error) { toast.error(error instanceof Error ? error.message : "Could not create staff account."); } finally { setBusy(false); } };
  const toggle = async (member: any) => { if (!store?.id || !canManage) return; const { error } = await db.from("staff_accounts").update({ is_active: !member.is_active, updated_at: new Date().toISOString() }).eq("id", member.id).eq("store_id", store.id); if (error) toast.error(error.message); else { toast.success(member.is_active ? "Staff suspended." : "Staff reactivated."); await load(); } };
  const remove = async (member: any) => { if (!store?.id || role !== "owner") return; if (!window.confirm(`Remove ${member.name} from this store?`)) return; const { error } = await db.from("staff_accounts").delete().eq("id", member.id).eq("store_id", store.id); if (error) toast.error(error.message); else { toast.success("Staff account removed."); setSelected(null); await load(); } };
  return <div className="space-y-5"><div className="flex flex-col gap-3 rounded-2xl border border-border bg-background p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">Existing staff system</p><p className="mt-1 text-sm text-muted-foreground">This page uses the existing staff RPCs and staff_accounts table. Authentication is not rebuilt.</p></div>{canManage && <Button onClick={() => setCreating(true)}><Users className="mr-2 size-4" />Add staff</Button>}</div><CardSection title="Staff" description="Select a staff member to inspect role, permissions, status and activity."><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead><tr className="border-b border-border text-left text-xs uppercase tracking-wide text-muted-foreground"><th className="px-3 py-3">Name</th><th className="px-3 py-3">Role</th><th className="px-3 py-3">Status</th><th className="px-3 py-3">Last active</th><th className="px-3 py-3">Created</th></tr></thead><tbody>{loading ? <tr><td colSpan={5} className="px-3 py-8 text-center text-muted-foreground">Loading staff…</td></tr> : staff.length === 0 ? <tr><td colSpan={5} className="px-3 py-8 text-center text-muted-foreground">No staff accounts yet.</td></tr> : staff.map((member) => <tr key={member.id} className="cursor-pointer border-b border-border/70 hover:bg-secondary/50" onClick={() => setSelected(member)}><td className="px-3 py-3 font-semibold">{member.name}</td><td className="px-3 py-3 capitalize">{member.role}</td><td className="px-3 py-3"><span className={`rounded-full px-2 py-1 text-xs font-semibold ${member.is_active ? "bg-accent-soft text-accent-ink" : "bg-secondary text-muted-foreground"}`}>{member.is_active ? "Active" : "Suspended"}</span></td><td className="px-3 py-3 text-muted-foreground">{member.last_login_at ? new Date(member.last_login_at).toLocaleString() : "Never"}</td><td className="px-3 py-3 text-muted-foreground">{member.created_at ? new Date(member.created_at).toLocaleDateString() : "Unknown"}</td></tr>)}</tbody></table></div></CardSection>{selected && <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true" onMouseDown={(e) => { if (e.currentTarget === e.target) setSelected(null); }}><div className="absolute inset-0 bg-black/50 backdrop-blur-sm"/><div className="relative z-10 w-full max-w-lg rounded-2xl border border-border bg-background p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Staff details</p><h3 className="mt-1 text-xl font-bold">{selected.name}</h3></div><Button variant="ghost" size="icon" onClick={() => setSelected(null)}><X className="size-4"/></Button></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><Detail label="Role" value={selected.role}/><Detail label="Status" value={selected.is_active ? "Active" : "Suspended"}/><Detail label="Last active" value={selected.last_login_at ? new Date(selected.last_login_at).toLocaleString() : "Never"}/><Detail label="Created" value={selected.created_at ? new Date(selected.created_at).toLocaleString() : "Unknown"}/></div><div className="mt-5 rounded-xl border border-border bg-surface p-4"><p className="text-sm font-semibold">Permissions</p><p className="mt-1 text-sm text-muted-foreground">Permissions are derived from the existing Strap staff role model. Role: {selected.role}.</p></div><div className="mt-5 flex flex-wrap gap-2"><Button variant="outline" disabled={!canManage} onClick={() => void toggle(selected)}>{selected.is_active ? "Suspend" : "Reactivate"}</Button>{role === "owner" && <Button variant="outline" className="text-destructive" onClick={() => void remove(selected)}>Remove</Button>}<Button variant="ghost" disabled title="PIN reset is not exposed by the existing staff API">Reset access</Button></div><p className="mt-3 text-xs text-muted-foreground">PIN reset is left disabled because the existing production staff API does not expose a safe reset operation. No fake reset is performed.</p></div></div>}{creating && <div className="fixed inset-0 z-50 flex items-center justify-center p-4" role="dialog" aria-modal="true"><div className="absolute inset-0 bg-black/50 backdrop-blur-sm"/><div className="relative z-10 w-full max-w-lg rounded-2xl border border-border bg-background p-6 shadow-2xl"><div className="flex items-start justify-between"><div><h3 className="text-xl font-bold">Add staff</h3><p className="mt-1 text-sm text-muted-foreground">Create an account through the existing atomic staff RPC.</p></div><Button variant="ghost" size="icon" onClick={() => setCreating(false)}><X className="size-4"/></Button></div><div className="mt-5 space-y-4"><Field label="Name" value={form.name} onChange={(v) => setForm({ ...form, name: v })}/><SelectField label="Role" value={form.role} onChange={(v) => setForm({ ...form, role: v })} options={["manager", "cashier", "inventory", "sales", "viewer"]}/><Field label="PIN" value={form.pin} onChange={(v) => setForm({ ...form, pin: v.replace(/\D/g, "").slice(0, 6) })} type="password" placeholder="4–6 digits"/></div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setCreating(false)} disabled={busy}>Cancel</Button><Button onClick={() => void create()} disabled={busy}>{busy ? "Creating…" : "Create staff"}</Button></div></div></div>}</div>;
}

function Detail({ label, value }: { label: string; value: string }) { return <div className="rounded-xl border border-border p-3"><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-sm font-semibold capitalize">{value}</p></div>; }

const preferenceRows = [
  ["orders_new", "New order", "Notify when a new order is received."], ["orders_cancelled", "Cancelled order", "Notify when an order is cancelled."], ["orders_fulfilled", "Fulfilled order", "Notify when an order is fulfilled."], ["inventory_low", "Low stock", "Notify when a product reaches the configured threshold."], ["inventory_out", "Out of stock", "Notify when a product reaches zero available stock."], ["inventory_adjusted", "Stock adjustment", "Notify when stock is manually adjusted."], ["customers_new", "New customer", "Notify when a new customer is created."], ["customers_messages", "Customer messages", "Notify about customer-facing messages where supported."], ["staff_changes", "Staff changes", "Notify owners and managers about staff changes."], ["staff_invites", "Staff invitations", "Notify when a staff invitation is created or changed."],
];

function NotificationsPage() {
  const { store, advanced, loading, reload } = useStoreData(); const { role } = useStoreContext(); const canManage = role === "owner" || role === "manager"; const current = advanced.notifications ?? {}; const [values, setValues] = useState<Record<string, boolean>>(current); const [initial, setInitial] = useState<Record<string, boolean>>(current); const [saving, setSaving] = useState(false); useEffect(() => { const next = advanced.notifications ?? {}; setValues(next); setInitial(next); }, [advanced.notifications]); if (loading) return <LoadingState />; const dirty = JSON.stringify(values) !== JSON.stringify(initial); const save = async () => { if (!store?.id || !canManage) return; setSaving(true); try { await saveAdvanced(store.id, advanced, { notifications: values }); setInitial(values); await reload(); toast.success("Notification preferences saved."); } catch (error) { toast.error(error instanceof Error ? error.message : "Could not save notifications."); } finally { setSaving(false); } }; return <div className="space-y-5">{[["Orders", preferenceRows.slice(0,3)], ["Inventory", preferenceRows.slice(3,6)], ["Customers", preferenceRows.slice(6,8)], ["Staff", preferenceRows.slice(8)]].map(([title, rows]) => <CardSection key={String(title)} title={String(title)}>{(rows as string[][]).map(([key, label, description]) => <ToggleRow key={key} label={label} description={description} checked={values[key] !== false} onChange={(value) => setValues((currentValues) => ({ ...currentValues, [key]: value }))} />)}</CardSection>)}{!canManage && <ReadOnlyNotice /> }<SaveBar dirty={dirty && canManage} saving={saving} onDiscard={() => setValues(initial)} onSave={() => void save()} /></div>;
}

function ReceiptsPage() {
  const { store, advanced, loading, reload } = useStoreData(); const { role } = useStoreContext(); const canManage = role === "owner" || role === "manager"; const base = advanced.receipts ?? {}; const [form, setForm] = useState<any>(base); const [initial, setInitial] = useState<any>(base); const [saving, setSaving] = useState(false); useEffect(() => { const next = advanced.receipts ?? {}; setForm(next); setInitial(next); }, [advanced.receipts]); if (loading) return <LoadingState />; const update = (key: string, value: unknown) => setForm((current: any) => ({ ...current, [key]: value })); const dirty = JSON.stringify(form) !== JSON.stringify(initial); const save = async () => { if (!store?.id || !canManage) return; setSaving(true); try { await saveAdvanced(store.id, advanced, { receipts: form }); setInitial(form); await reload(); toast.success("Receipt settings saved."); } catch (error) { toast.error(error instanceof Error ? error.message : "Could not save receipts."); } finally { setSaving(false); } }; return <div className="space-y-5"><CardSection title="Receipt branding"><div className="grid gap-4 sm:grid-cols-2"><Field label="Logo URL" value={form.logoUrl ?? ""} onChange={(v) => update("logoUrl", v)} placeholder="https://"/><Field label="Business name" value={form.businessName ?? store.name} onChange={(v) => update("businessName", v)}/><Field label="Address" value={form.address ?? ""} onChange={(v) => update("address", v)}/><Field label="Phone" value={form.phone ?? ""} onChange={(v) => update("phone", v)}/><Field label="Email" value={form.email ?? ""} onChange={(v) => update("email", v)}/></div></CardSection><CardSection title="Receipt content"><div className="grid gap-4"><Field label="Header" value={form.header ?? "Thank you for your purchase"} onChange={(v) => update("header", v)}/><Textarea value={form.footer ?? "Powered by Strap"} onChange={(e) => update("footer", e.target.value)} placeholder="Footer"/><Textarea value={form.thankYou ?? "Thank you for shopping with us."} onChange={(e) => update("thankYou", e.target.value)} placeholder="Thank-you message"/><div className="grid gap-4 sm:grid-cols-2"><Field label="Tax ID" value={form.taxId ?? ""} onChange={(v) => update("taxId", v)}/><Field label="Receipt prefix" value={form.prefix ?? "STRAP"} onChange={(v) => update("prefix", v)}/></div></div></CardSection><CardSection title="Printing"><div className="grid gap-3"><ToggleRow label="Automatic printing" description="Print supported receipts automatically after eligible sales." checked={Boolean(form.autoPrint)} onChange={(v) => update("autoPrint", v)}/><SelectField label="Print copies" value={String(form.copies ?? 1)} onChange={(v) => update("copies", Number(v))} options={["1", "2", "3"]}/><SelectField label="Paper size" value={form.paperSize ?? "80mm"} onChange={(v) => update("paperSize", v)} options={["58mm", "80mm", "A4"]}/></div></CardSection><CardSection title="Preview"><div className="mx-auto max-w-sm rounded-xl border border-border bg-white p-5 font-mono text-xs text-black"><div className="text-center font-bold">{form.businessName ?? store.name}</div><div className="mt-2 text-center">{form.header ?? "Thank you for your purchase"}</div><div className="my-4 border-t border-dashed border-black/30"/><div className="flex justify-between"><span>Product</span><span>1 × 0.00</span></div><div className="mt-3 border-t border-dashed border-black/30 pt-3 text-center">{form.thankYou ?? "Thank you for shopping with us."}</div><div className="mt-2 text-center">{form.footer ?? "Powered by Strap"}</div></div></CardSection>{!canManage && <ReadOnlyNotice />}<SaveBar dirty={dirty && canManage} saving={saving} onDiscard={() => setForm(initial)} onSave={() => void save()} /></div>;
}

function OnlineStorePage() {
  const { store, online, config, loading, reload } = useStoreData(); const { role } = useStoreContext(); const canManage = role === "owner" || role === "manager"; const [form, setForm] = useState<any>(null); const [initial, setInitial] = useState<any>(null); const [saving, setSaving] = useState(false); useEffect(() => { if (!store) return; const next = { status: online?.is_published ? "Online" : online?.setup_completed ? "Offline" : "Coming Soon", slug: online?.slug ?? "", homepage: "Storefront home", productVisibility: config?.sections?.find?.((section: any) => section.id === "product-grid")?.enabled !== false, collectionVisibility: true, seoTitle: config?.seo?.title ?? "", metaDescription: config?.seo?.description ?? "", noIndex: Boolean(config?.seo?.noIndex), socialImage: config?.seo?.socialImage ?? "" }; setForm(next); setInitial(next); }, [config, online, store]); if (loading || !form) return <LoadingState />; const dirty = JSON.stringify(form) !== JSON.stringify(initial); const update = (key: string, value: unknown) => setForm((current: any) => ({ ...current, [key]: value })); const save = async () => { if (!store?.id || !canManage) return; setSaving(true); try { const published = form.status === "Online"; const { error: onlineError } = await db.from("online_stores").upsert({ store_id: store.id, slug: form.slug, display_name: online?.display_name ?? store.name, logo_url: online?.logo_url ?? "", display_email: online?.display_email ?? "", display_phone: online?.display_phone ?? "", description: online?.description ?? "", shipping_note: online?.shipping_note ?? "", checkout_note: online?.checkout_note ?? "", is_published: published, setup_completed: form.status !== "Coming Soon", terms_version: online?.terms_version ?? "2026-08-18", privacy_version: online?.privacy_version ?? "2026-08-18", accepted_terms_at: online?.accepted_terms_at ?? null, accepted_privacy_at: online?.accepted_privacy_at ?? null, updated_at: new Date().toISOString() }, { onConflict: "store_id" }); if (onlineError) throw new Error(onlineError.message); const sections = config?.sections ?? []; const nextSections = sections.map((section: any) => section.id === "product-grid" ? { ...section, enabled: Boolean(form.productVisibility) } : section); const { error: configError } = await db.from("storefront_configs").upsert({ store_id: store.id, template: config?.template ?? "minimal-commerce", theme: config?.theme ?? {}, branding: config?.branding ?? {}, navigation: config?.navigation ?? { links: [] }, sections: nextSections, seo: { ...(config?.seo ?? {}), title: form.seoTitle, description: form.metaDescription, noIndex: form.noIndex, socialImage: form.socialImage }, custom_css: config?.custom_css ?? "", published: config?.published ?? false, version: config?.version ?? 1, updated_at: new Date().toISOString() }, { onConflict: "store_id" }); if (configError) throw new Error(configError.message); setInitial(form); await reload(); toast.success("Online store settings saved."); } catch (error) { toast.error(error instanceof Error ? error.message : "Could not save online-store settings."); } finally { setSaving(false); } }; return <div className="space-y-5"><CardSection title="Store status"><SelectField label="Status" value={form.status} onChange={(v) => update("status", v)} options={["Online", "Offline", "Coming Soon"]}/></CardSection><CardSection title="Storefront"><div className="grid gap-4 sm:grid-cols-2"><Field label="Store URL slug" value={form.slug} onChange={(v) => update("slug", v)} placeholder="my-store"/><Field label="Homepage" value={form.homepage} onChange={(v) => update("homepage", v)}/></div><div className="mt-4 grid gap-3"><ToggleRow label="Product visibility" description="Keep the main product grid available to customers." checked={form.productVisibility} onChange={(v) => update("productVisibility", v)}/><ToggleRow label="Collection visibility" description="Show collection/category navigation where supported." checked={form.collectionVisibility} onChange={(v) => update("collectionVisibility", v)}/></div></CardSection><CardSection title="SEO"><div className="grid gap-4"><Field label="Page title" value={form.seoTitle} onChange={(v) => update("seoTitle", v)}/><Textarea value={form.metaDescription} onChange={(e) => update("metaDescription", e.target.value)} placeholder="Meta description"/><Field label="Social preview image" value={form.socialImage} onChange={(v) => update("socialImage", v)} placeholder="https://"/><ToggleRow label="Search visibility" description="Allow search engines to index the storefront." checked={!form.noIndex} onChange={(v) => update("noIndex", !v)}/></div></CardSection><CardSection title="Storefront actions"><div className="flex flex-wrap gap-2"><Link to="/online-store/customize" className="inline-flex items-center rounded-xl border border-border px-4 py-2.5 text-sm font-semibold hover:bg-secondary">Customize storefront</Link><Link to={form.slug ? `/store/${form.slug}` : "/online-store"} className="inline-flex items-center rounded-xl border border-border px-4 py-2.5 text-sm font-semibold hover:bg-secondary">Preview storefront</Link><Link to={form.slug ? `/store/${form.slug}` : "/online-store"} className="inline-flex items-center rounded-xl bg-foreground px-4 py-2.5 text-sm font-semibold text-background">Open storefront</Link></div><p className="mt-3 text-xs text-muted-foreground">These actions use the existing storefront tools. Settings does not pretend to be the visual editor.</p></CardSection>{!canManage && <ReadOnlyNotice />}<SaveBar dirty={dirty && canManage} saving={saving} onDiscard={() => setForm(initial)} onSave={() => void save()} /></div>;
}

function CheckoutPage() {
  return <AdvancedGroupPage group="checkout" title="Checkout & sales" description="Persist checkout and POS preferences in the existing store_advanced_settings structure." rows={[["requireEmail","Require customer email","Collect an email address where checkout supports it."],["requirePhone","Require phone","Collect a phone number during supported checkout flows."],["guestCheckout","Guest checkout","Allow customers to place orders without a customer account."],["orderConfirmation","Order confirmation","Show confirmation after a completed order."],["allowDiscounts","Allow discounts","Enable discount handling where supported."],["discountCodes","Discount codes","Allow configured discount codes."],["stockDeduction","Stock deduction","Deduct inventory when supported sales complete."],["posSounds","POS sounds","Play feedback sounds for POS actions."],["receiptPrinting","Receipt printing","Enable supported receipt printing behaviour."],["barcodeScanner","Barcode scanner","Keep barcode scanning behaviour enabled."],["customerSelection","Customer selection","Allow cashier selection of an existing customer."]]} />;
}

function InventoryPage() {
  return <AdvancedGroupPage group="inventory" title="Inventory" description="Persist inventory behaviour in the existing advanced settings table and use the store's existing low-stock threshold." rows={[["trackInventory","Track inventory","Update inventory quantities as supported sales are completed."],["allowNegative","Allow negative inventory","Permit sales below zero. Leave disabled for protection."],["lowStockThreshold","Low-stock threshold","Use the store-level threshold when generating low-stock alerts."],["outOfStockBehaviour","Out-of-stock behaviour","Choose how storefront products behave when unavailable."],["costMethod","Cost method","Choose the basis used by future inventory valuation analytics."],["inventoryValuation","Inventory valuation","Enable inventory valuation reporting where supported."],["branchAware","Branch-aware inventory","Keep stock operations aware of branch-level quantities."],["defaultBranch","Default branch","Use the existing default branch for store operations."],["transferRules","Transfer rules","Keep branch transfer controls enabled."],["lowStockAlerts","Low-stock notifications","Notify the team when stock reaches the threshold."],["outOfStockAlerts","Out-of-stock notifications","Notify the team when stock reaches zero."]]} />;
}

function AdvancedGroupPage({ group, title, description, rows }: { group: string; title: string; description: string; rows: string[][] }) {
  const { store, advanced, loading, reload } = useStoreData(); const { role } = useStoreContext(); const canManage = role === "owner" || role === "manager"; const current = advanced[group] ?? {}; const [values, setValues] = useState<any>(current); const [initial, setInitial] = useState<any>(current); const [saving, setSaving] = useState(false); useEffect(() => { const next = advanced[group] ?? {}; setValues(next); setInitial(next); }, [advanced, group]); if (loading) return <LoadingState />; const dirty = JSON.stringify(values) !== JSON.stringify(initial); const update = (key: string, value: unknown) => setValues((currentValues: any) => ({ ...currentValues, [key]: value })); const save = async () => { if (!store?.id || !canManage) return; setSaving(true); try { await saveAdvanced(store.id, advanced, { [group]: values }); setInitial(values); await reload(); toast.success(`${title} saved.`); } catch (error) { toast.error(error instanceof Error ? error.message : `Could not save ${title.toLowerCase()}.`); } finally { setSaving(false); } }; return <div className="space-y-5"><CardSection title={title} description={description}><div className="grid gap-3">{rows.map(([key, label, text], index) => index === 2 && group === "inventory" ? <div key={key} className="rounded-xl border border-border p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-semibold">{label}</p><p className="mt-1 text-xs text-muted-foreground">{text}</p></div><Input className="sm:max-w-[180px]" type="number" min="0" value={String(values[key] ?? 5)} onChange={(e) => update(key, Number(e.target.value))}/></div></div> : <ToggleRow key={key} label={label} description={text} checked={values[key] !== false} onChange={(v) => update(key, v)} />)}</div></CardSection>{group === "inventory" && <CardSection title="Valuation method"><SelectField label="Cost method" value={values.costMethodName ?? "Weighted average"} onChange={(v) => update("costMethodName", v)} options={["Weighted average", "FIFO"]}/><div className="mt-4"><ToggleRow label="Inventory valuation" description="Store the preference for future valuation reports without fabricating a current valuation engine." checked={values.inventoryValuation !== false} onChange={(v) => update("inventoryValuation", v)}/></div></CardSection>}{!canManage && <ReadOnlyNotice />}<SaveBar dirty={dirty && canManage} saving={saving} onDiscard={() => setValues(initial)} onSave={() => void save()} /></div>;
}

function SecurityPage() {
  const { store, userId } = useStoreContext(); const [email, setEmail] = useState(""); const [verified, setVerified] = useState(false); const [passwordChangedAt, setPasswordChangedAt] = useState<string | null>(null); const [alerts, setAlerts] = useState(true); const [saving, setSaving] = useState(false);
  useEffect(() => { void (async () => { const [{ data: user }, { data: security }] = await Promise.all([supabase.auth.getUser(), db.from("account_security_settings").select("security_alerts").eq("user_id", userId).maybeSingle()]); setEmail(user.user?.email ?? ""); setVerified(Boolean(user.user?.email_confirmed_at)); setPasswordChangedAt(user.user?.updated_at ?? null); setAlerts(security?.security_alerts !== false); })(); }, [userId]);
  const save = async () => { setSaving(true); const { error } = await db.from("account_security_settings").upsert({ user_id: userId, security_alerts: alerts, updated_at: new Date().toISOString() }, { onConflict: "user_id" }); setSaving(false); if (error) toast.error(error.message); else toast.success("Security preferences saved."); };
  return <div className="space-y-5"><CardSection title="Account security"><div className="grid gap-3 sm:grid-cols-2"><Detail label="Verified email" value={verified ? email : "Verification required"}/><Detail label="Password status" value={passwordChangedAt ? `Updated ${new Date(passwordChangedAt).toLocaleDateString()}` : "No timestamp available"}/></div><div className="mt-4 flex flex-wrap gap-2"><Link to="/settings/password" className="inline-flex items-center rounded-xl bg-foreground px-4 py-2.5 text-sm font-semibold text-background">Change password</Link><Link to="/settings/sessions" className="inline-flex items-center rounded-xl border border-border px-4 py-2.5 text-sm font-semibold">Active sessions</Link></div></CardSection><CardSection title="Authentication"><div className="grid gap-3"><ToggleRow label="Email verification" description="Strap already enforces verified email before protected workspace access." checked={verified} onChange={() => undefined}/><SelectField label="Session timeout" value="Managed by Supabase Auth" onChange={() => undefined} options={["Managed by Supabase Auth"]}/><p className="text-xs text-muted-foreground">Staff PIN settings remain in the existing staff system; this page does not duplicate PIN storage.</p></div></CardSection><CardSection title="Security activity"><p className="text-sm leading-6 text-muted-foreground">Security activity is shown from the existing Supabase Auth-backed session and audit tooling. Strap does not fabricate events.</p></CardSection><CardSection title="Security alerts"><ToggleRow label="Account security alerts" description="Persist whether account security notifications should remain enabled." checked={alerts} onChange={setAlerts}/><Button className="mt-4" onClick={() => void save()} disabled={saving}>{saving ? "Saving…" : "Save preferences"}</Button></CardSection><div className="rounded-2xl border border-accent/20 bg-accent-soft p-4 text-sm text-muted-foreground">Session revocation and detailed authentication history are available on the dedicated Sessions page.</div></div>;
}

function PaymentsPage() { return <div className="rounded-2xl border border-dashed border-border bg-background p-8 text-center sm:p-12"><div className="mx-auto flex size-12 items-center justify-center rounded-2xl bg-secondary"><WalletCards className="size-6 text-muted-foreground"/></div><h3 className="mt-5 text-xl font-bold">Payments</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted-foreground">We're preparing secure payment infrastructure for Strap businesses.</p><span className="mt-6 inline-flex cursor-not-allowed items-center rounded-xl border border-border px-4 py-2.5 text-sm font-semibold text-muted-foreground">Notify me</span><p className="mt-3 text-xs text-muted-foreground">No Stripe, Paystack, Flutterwave or other processor is connected from this page.</p></div>; }

function PasswordPage() {
  const { userId } = useStoreContext(); const [email, setEmail] = useState(""); const [otpSentAt, setOtpSentAt] = useState<number | null>(null); const [otp, setOtp] = useState(""); const [newPassword, setNewPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [busy, setBusy] = useState(false); const [resendIn, setResendIn] = useState(0); const [verified, setVerified] = useState(false); useEffect(() => { void supabase.auth.getUser().then(({ data }) => setEmail(data.user?.email ?? "")); }, [userId]); useEffect(() => { if (!resendIn) return; const timer = window.setInterval(() => setResendIn((value) => Math.max(0, value - 1)), 1000); return () => window.clearInterval(timer); }, [resendIn]); const strength = passwordStrength(newPassword); const requestOtp = async () => { if (!email) return; setBusy(true); const { error } = await supabase.auth.signInWithOtp({ email, options: { shouldCreateUser: false } }); setBusy(false); if (error) return toast.error(error.message); setOtpSentAt(Date.now()); setResendIn(60); toast.success("Verification code sent to your verified email."); }; const verify = async () => { if (!/^\d{6}$/.test(otp)) return toast.error("Enter the 6-digit verification code."); if (strength.score < 3) return toast.error("Use a stronger password."); if (newPassword !== confirm) return toast.error("The passwords do not match."); setBusy(true); const { error: verifyError } = await supabase.auth.verifyOtp({ email, token: otp, type: "email" }); if (verifyError) { setBusy(false); return toast.error(verifyError.message); } setVerified(true); const { error } = await supabase.auth.updateUser({ password: newPassword }); setBusy(false); if (error) return toast.error(error.message); setOtp(""); setNewPassword(""); setConfirm(""); setOtpSentAt(null); setVerified(false); toast.success("Password changed successfully."); }; return <div className="space-y-5"><CardSection title="Verify your email" description={`Supabase will send a one-time verification code to ${email || "your verified email"}.`}><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><span className="flex size-10 items-center justify-center rounded-xl bg-accent-soft"><LockKeyhole className="size-5 text-accent-ink"/></span><div><p className="font-semibold">Email verification</p><p className="text-sm text-muted-foreground">Step 1 — request an OTP before changing the password.</p></div></div><Button onClick={() => void requestOtp()} disabled={busy || resendIn > 0}>{resendIn > 0 ? `Resend in ${resendIn}s` : otpSentAt ? "Resend OTP" : "Request OTP"}</Button></div>{otpSentAt && <p className="mt-4 text-xs text-muted-foreground">Code requested {new Date(otpSentAt).toLocaleTimeString()}.</p>}</CardSection><CardSection title="Set a new password" description="Step 2 — verify the OTP, then update the authenticated Supabase user." className={!otpSentAt ? "opacity-60" : ""}><div className="grid gap-4 sm:grid-cols-2"><Field label="OTP" value={otp} onChange={(v) => setOtp(v.replace(/\D/g, "").slice(0, 6))} placeholder="6-digit code" disabled={!otpSentAt}/><div/><Field label="New password" value={newPassword} onChange={setNewPassword} type="password" disabled={!otpSentAt}/><Field label="Confirm password" value={confirm} onChange={setConfirm} type="password" disabled={!otpSentAt}/></div><div className="mt-4 rounded-xl border border-border bg-surface p-4"><div className="flex items-center justify-between text-xs"><span className="font-semibold">Password strength</span><span>{strength.label}</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-accent transition-all" style={{ width: `${strength.score * 25}%` }}/></div><p className="mt-2 text-xs text-muted-foreground">Use 8+ characters with upper/lowercase letters, a number and a symbol.</p></div><Button className="mt-5" onClick={() => void verify()} disabled={busy || !otpSentAt}>{busy ? "Verifying…" : "Verify OTP & change password"}</Button></CardSection>{verified && <div className="rounded-xl border border-accent/20 bg-accent-soft p-4 text-sm font-medium">Email verification succeeded. Password update is being applied through Supabase Auth.</div>}</div>;
}

function passwordStrength(value: string) { let score = 0; if (value.length >= 8) score++; if (/[A-Z]/.test(value) && /[a-z]/.test(value)) score++; if (/\d/.test(value)) score++; if (/[^A-Za-z0-9]/.test(value)) score++; return { score, label: ["Very weak", "Weak", "Fair", "Strong", "Very strong"][score] }; }

function SessionsPage() {
  const [sessions, setSessions] = useState<any[]>([]); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const load = useCallback(async () => { setLoading(true); const { data, error } = await supabase.functions.invoke("account-security", { body: { action: "get" } }); if (error) toast.error(error.message); setSessions(data?.sessions ?? []); setLoading(false); }, []); useEffect(() => { void load(); }, [load]); const revoke = async (sessionId: string) => { setBusy(true); const { data, error } = await supabase.functions.invoke("account-security", { body: { action: "revoke", sessionId } }); setBusy(false); if (error) return toast.error(error.message); if (!data?.revoked) return toast.error("Session could not be revoked."); toast.success("Session revoked."); await load(); }; const revokeOthers = async () => { setBusy(true); const { data, error } = await supabase.functions.invoke("account-security", { body: { action: "revoke_all_others" } }); setBusy(false); if (error) return toast.error(error.message); toast.success(`${data?.revoked ?? 0} other session(s) signed out.`); await load(); }; return <div className="space-y-5"><CardSection title="Active sessions" description="Only fields returned by the existing account-security Edge Function are displayed."><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => void load()} disabled={loading}><CircleHelp className="mr-2 size-4"/>Refresh</Button><Button onClick={() => void revokeOthers()} disabled={busy || sessions.filter((session) => !session.current).length === 0}><LockKeyhole className="mr-2 size-4"/>Sign out other devices</Button></div><div className="mt-5 grid gap-3">{loading ? <LoadingState /> : sessions.length === 0 ? <EmptyState text="No session records were returned."/> : sessions.map((session) => <div key={session.session_id} className="rounded-xl border border-border bg-surface p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{deviceName(session.user_agent)}</p>{session.current && <span className="rounded-full bg-accent-soft px-2 py-1 text-[10px] font-bold uppercase text-accent-ink">Current session</span>}</div><p className="mt-1 text-xs text-muted-foreground">{session.ip ? `IP ${session.ip}` : "IP not recorded"} · Last active {session.updated_at ? new Date(session.updated_at).toLocaleString() : "Unknown"}</p><p className="mt-1 max-w-2xl truncate text-xs text-muted-foreground">{session.user_agent ?? "User agent not recorded"}</p></div>{!session.current && <Button variant="outline" onClick={() => void revoke(session.session_id)} disabled={busy}>Sign out</Button>}</div><p className="mt-3 text-[11px] text-muted-foreground">Created {session.created_at ? new Date(session.created_at).toLocaleString() : "Unknown"} · Refreshed {session.refreshed_at ? new Date(session.refreshed_at).toLocaleString() : "Unknown"}</p></div>)}</div></CardSection><CardSection title="Security activity" description="Authentication IP history is exposed by the same authenticated security function when available."><p className="text-sm leading-6 text-muted-foreground">For the current implementation, detailed IP history remains available through the Security page's authenticated session service. No device or location data is fabricated here.</p></CardSection><Link to="/settings/sessions/revoke" className="inline-flex items-center gap-2 text-sm font-semibold text-accent-ink">Open sign-out confirmation <ArrowRight className="size-4"/></Link></div>;
}

function deviceName(userAgent: string | null) { if (!userAgent) return "Unknown device"; if (/iphone|ipad|android/i.test(userAgent)) return "Mobile device"; if (/macintosh|mac os/i.test(userAgent)) return "Mac browser"; if (/windows/i.test(userAgent)) return "Windows browser"; if (/linux/i.test(userAgent)) return "Linux browser"; return "Desktop browser"; }

export function RevokeSessionsPage() {
  const [busy, setBusy] = useState(false); const revoke = async () => { setBusy(true); const { data, error } = await supabase.functions.invoke("account-security", { body: { action: "revoke_all_others" } }); setBusy(false); if (error) return toast.error(error.message); toast.success(`${data?.revoked ?? 0} other session(s) have been signed out.`); }; return <div className="mx-auto max-w-xl rounded-2xl border border-border bg-background p-6 sm:p-8"><div className="flex size-12 items-center justify-center rounded-2xl bg-secondary"><LockKeyhole className="size-6"/></div><h2 className="mt-5 text-2xl font-bold">Sign out other devices?</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">This will sign you out everywhere except the device you're currently using.</p><div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><Link to="/settings/sessions" className="inline-flex items-center justify-center rounded-xl px-4 py-2.5 text-sm font-semibold hover:bg-secondary">Cancel</Link><Button onClick={() => void revoke()} disabled={busy}>{busy ? "Signing out…" : "Sign out other devices"}</Button></div></div>;
}

function AdvancedPage() {
  const { store, advanced, loading, reload } = useStoreData(); const { role } = useStoreContext(); const canManage = role === "owner" || role === "manager"; const groups = [{ key: "operations", title: "Store operations", rows: [["lowStockAlerts","Low stock alerts"],["outOfStockAlerts","Out-of-stock alerts"],["orderNotifications","Order notifications"],["customerNotifications","Customer notifications"]] }, { key: "pos", title: "POS", rows: [["posSounds","POS sounds"],["barcodeAutofocus","Barcode autofocus"],["autoReceiptPrinting","Automatic receipt printing"]] }, { key: "inventory", title: "Inventory", rows: [["negativeStockProtection","Negative-stock protection"],["inventoryValuation","Inventory valuation"],["branchAwareInventory","Branch-aware inventory"]] }, { key: "security", title: "Security", rows: [["activityLogging","Activity logging"],["destructiveConfirmations","Destructive-action confirmations"],["sessionTimeout","Session timeout"],["staffPin","Staff PIN"]] }, { key: "storefront", title: "Storefront", rows: [["searchSuggestions","Search suggestions"],["drafts","Drafts"],["seo","SEO"],["socialSharing","Social sharing"]] }, { key: "developer", title: "Developer", rows: [["apiAccess","API access"],["webhooks","Webhooks"]] }, { key: "experimental", title: "Experimental", rows: [["loyaltyPoints","Loyalty points"],["discountCodes","Discount codes"],["aiAutomation","AI automation"]] }]; const [values, setValues] = useState<any>(advanced); const [initial, setInitial] = useState<any>(advanced); const [saving, setSaving] = useState(false); useEffect(() => { setValues(advanced); setInitial(advanced); }, [advanced]); if (loading) return <LoadingState />; const dirty = JSON.stringify(values) !== JSON.stringify(initial); const update = (group: string, key: string, value: boolean) => setValues((current: any) => ({ ...current, [group]: { ...(current[group] ?? {}), [key]: value } })); const save = async () => { if (!store?.id || !canManage) return; setSaving(true); try { const { error } = await db.from("store_advanced_settings").upsert({ store_id: store.id, settings: values, updated_at: new Date().toISOString() }, { onConflict: "store_id" }); if (error) throw new Error(error.message); setInitial(values); await reload(); toast.success("Advanced settings saved."); } catch (error) { toast.error(error instanceof Error ? error.message : "Could not save advanced settings."); } finally { setSaving(false); } }; return <div className="space-y-5">{groups.map((group) => <CardSection key={group.key} title={group.title}>{group.rows.map(([key, label]) => <ToggleRow key={key} label={label} description={advancedDescription(label)} checked={values[group.key]?.[key] !== false} onChange={(value) => update(group.key, key, value)} />)}</CardSection>)}<CardSection title="Developer controls" description="These controls reflect the existing database structures. Opening an API key or webhook management surface remains outside this settings page unless the corresponding production manager exists."><div className="grid gap-3"><div className="rounded-xl border border-border p-4"><p className="font-semibold">API access</p><p className="mt-1 text-sm text-muted-foreground">API keys already exist in Strap's database and are managed from Security for owners.</p><Link to="/settings/security" className="mt-3 inline-flex text-sm font-semibold text-accent-ink">Open Security <ArrowRight className="ml-1 size-4"/></Link></div><div className="rounded-xl border border-border p-4"><p className="font-semibold">Webhooks</p><p className="mt-1 text-sm text-muted-foreground">Webhook endpoints exist in the commerce schema, but no dedicated production settings manager is exposed here yet.</p></div></div></CardSection>{!canManage && <ReadOnlyNotice />}<SaveBar dirty={dirty && canManage} saving={saving} onDiscard={() => setValues(initial)} onSave={() => void save()} /></div>;
}

function advancedDescription(label: string) { return `${label} controls an existing Strap preference. Changes are persisted per store.`; }
function ReadOnlyNotice() { return <div className="rounded-xl border border-border bg-secondary/40 p-4 text-sm text-muted-foreground">You can view this setting, but only store owners and managers can save changes.</div>; }
function LoadingState() { return <div className="rounded-2xl border border-border bg-background p-8 text-sm text-muted-foreground">Loading settings…</div>; }
function EmptyState({ text }: { text: string }) { return <div className="rounded-xl border border-dashed border-border p-6 text-center text-sm text-muted-foreground">{text}</div>; }
